// CanvasServer is the server API for Canvas service.
// All implementations must embed UnimplementedCanvasServer
// for forward compatibility.
//
// canvas：画布文档（Vue Flow 快照整段存）+ 单节点执行（node run）+ 模板 + 提示词库。
// 接口约定见 docs/api/api-canvas.md；设计见 docs/design/xiaoqi-2026-10-30/00-需求分流与设计方案.md §6。
// 快照、工具参数、Java 目录这类前端私有 / 透传 JSON 一律用 JSON 文本（string）承接，服务端只校验不翻译。
// 时间字段一律 unix 毫秒。
//
// 用户 Bearer 透传：网关把请求的 Authorization 原文放进 gRPC metadata「x-user-authorization」，
// 调 Java 兼容工具（放大 / 扩图 / 重绘）与 Java 价目接口时原样带上。
type CanvasServer interface {
	// ---- 画布 ----
	ListCanvases(context.Context, *ListCanvasesReq) (*ListCanvasesResp, error)
	CreateCanvas(context.Context, *CreateCanvasReq) (*CanvasDoc, error)
	// 取画布：快照 + revision，运行态按每个节点最近一次 run 回填进 data
	GetCanvas(context.Context, *CanvasIdReq) (*CanvasDoc, error)
	// 保存：if_match_revision 不符且非 force → conflict=true（网关转 4002，data 带服务端 revision）
	SaveCanvas(context.Context, *SaveCanvasReq) (*SaveCanvasResp, error)
	DeleteCanvas(context.Context, *CanvasIdReq) (*Empty, error)
	SaveAsCanvas(context.Context, *SaveAsCanvasReq) (*CanvasDoc, error)
	// ---- 执行 ----
	RunNode(context.Context, *RunNodeReq) (*RunNodeResp, error)
	GetRun(context.Context, *RunIdReq) (*RunResult, error)
	CancelRun(context.Context, *RunIdReq) (*RunResult, error)
	ListRuns(context.Context, *ListRunsReq) (*ListRunsResp, error)
	// 选中候选：写回 run.selected_index（GET 画布回填 selectedCandidate 以它为准）
	SelectCandidate(context.Context, *SelectCandidateReq) (*RunResult, error)
	// 重新存入素材库：成功 run 的产物转存永久失败（library_status=failed）时把转存任务重置为待转存并立即执行；
	// 仅本人；已在转存中 / 已在素材库时幂等返回当前状态；同一 run 每分钟至多重置一次。返回 run（library_status 变为 pending）
	RetryLibraryCopy(context.Context, *RunIdReq) (*RunResult, error)
	// 只增（2026-11-11）：成功 run 某个图片候选的来源（仅本人、未删除）：私有引用（mr:// / mrw://，转存素材库前 / 失败 / 免费档）给 rid，
	// 否则给长期地址。供区域蒙版（POST /api/v1/studio/masks 的 canvas_request_id + candidate_index）按归属精确取图，不下发给前端。
	CandidateSource(context.Context, *CandidateSourceReq) (*CandidateSourceResp, error)
	// ---- 目录 ----
	Catalog(context.Context, *CatalogReq) (*CatalogResp, error)
	// 只增（2026-11-19）：生图预估点数（只读，不冻结）。与 RunNode 冻结同一个 Quote（同一 Charge：模型组 + 尺寸 + 张数 + 画质 + 参考图数），
	// 契约 §AE：GPT Image 2.6 报「最多 X 点（按实际成本结算）」，其余按张固定价。
	Estimate(context.Context, *EstimateReq) (*EstimateResp, error)
	// ---- 模板 ----
	ListTemplates(context.Context, *ListTemplatesReq) (*ListTemplatesResp, error)
	GetTemplate(context.Context, *TemplateIdReq) (*TemplateInfo, error)
	CreateTemplateFromCanvas(context.Context, *CreateTemplateFromCanvasReq) (*TemplateInfo, error)
	CreateCanvasFromTemplate(context.Context, *CreateCanvasFromTemplateReq) (*CanvasDoc, error)
	DeleteTemplate(context.Context, *TemplateIdReq) (*Empty, error)
	// ---- 提示词库 ----
	ListPrompts(context.Context, *ListPromptsReq) (*ListPromptsResp, error)
	CreatePrompt(context.Context, *UpsertPromptReq) (*PromptItem, error)
	UpdatePrompt(context.Context, *UpsertPromptReq) (*PromptItem, error)
	DeletePrompt(context.Context, *PromptIdReq) (*Empty, error)
	// ---- 运营后台 ----
	AdminListRuns(context.Context, *AdminListRunsReq) (*AdminListRunsResp, error)
	AdminForceFailRun(context.Context, *AdminRunReq) (*Empty, error)
	AdminListTemplates(context.Context, *AdminListTemplatesReq) (*AdminListTemplatesResp, error)
	AdminUpsertOfficialTemplate(context.Context, *AdminUpsertTemplateReq) (*TemplateInfo, error)
	AdminToggleTemplate(context.Context, *AdminToggleReq) (*Empty, error)
	AdminListPrompts(context.Context, *AdminListPromptsReq) (*AdminListPromptsResp, error)
	AdminUpsertOfficialPrompt(context.Context, *AdminUpsertPromptReq) (*PromptItem, error)
	AdminTogglePrompt(context.Context, *AdminToggleReq) (*Empty, error)
	AdminCostSummary(context.Context, *AdminCostSummaryReq) (*AdminCostSummaryResp, error)
	// ---- 智能体工具（只增，2026-11-13）----
	// 执行一个画布智能体工具（清单见 app/canvas/agenttool；Function Call 与 MCP 两种形式都走这里）。
	// user_id 只来自网关鉴权；工具业务错误放在 is_error + result（{error_code,message,retryable}），不作 gRPC 错误返回。
	// 设计见 docs/design/canvas-agent-tools.md
	AgentCall(context.Context, *AgentCallReq) (*AgentCallResp, error)
	// 画布当前 revision（只读元数据，不读快照）：网关 SSE 归属校验 / 心跳对账 / 降级轮询
	GetCanvasRevision(context.Context, *CanvasIdReq) (*CanvasRevisionResp, error)
	// ---- MCP 访问令牌（只增，2026-11-14；Go_V1.0.42）----
	// 外部 MCP 客户端专用令牌：明文只在创建时返回一次，库里只存 sha256 + 前缀；每人最多 10 个生效中的令牌。
	// 管理（建 / 列 / 吊销）只接受登录令牌（网关校验）；校验由网关 Auth 前置调用（网关侧 Redis 缓存，吊销时网关删缓存）。
	CreateMcpToken(context.Context, *CreateMcpTokenReq) (*CreateMcpTokenResp, error)
	ListMcpTokens(context.Context, *ListMcpTokensReq) (*ListMcpTokensResp, error)
	RevokeMcpToken(context.Context, *RevokeMcpTokenReq) (*RevokeMcpTokenResp, error)
	// 按令牌哈希校验：不存在 / 已吊销 / 已过期 → Unauthorized（reason 区分）；成功时记最后使用时间与 IP
	VerifyMcpToken(context.Context, *VerifyMcpTokenReq) (*VerifyMcpTokenResp, error)
	mustEmbedUnimplementedCanvasServer()
}

